// Spatial Locality: Row-major access is optimal (C/C++)
// Accessing elements sequentially maximizes cache line reuse (Stride-1)
const int R = 100, C = 100;
int matrix[R][C];
long sum = 0;

// Optimal: Row-major (i inner loop)
for (int i = 0; i < R; i++) {
    for (int j = 0; j < C; j++) {
        sum += matrix[i][j];
    }
}
